def rotate_90(grid):
    rows = len(grid)
    cols = len(grid[0])
    rotated = [[0]*rows for _ in range(cols)]
    for r in range(rows):
        for c in range(cols):
            rotated[c][rows-1-r] = grid[r][c]
    return rotated

rotated = rotate_90(input_grid)
