# Try 180-degree rotation (flip both axes)
def rotate_180(grid):
    rows = len(grid)
    cols = len(grid[0])
    rotated = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            rotated[rows-1-r][cols-1-c] = grid[r][c]
    return rotated

rotated_180 = rotate_180(input_grid)
action = {"action": "submit", "grid": rotated_180}
print(f"Submitting 180-degree rotated grid")

# Try: fill all cells in rows or columns with scattered cells with the most common color (3)

def fill_rows_cols_ordered(grid, fill_color=3):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    # Find which rows and cols have non-zero cells
    active_rows = set()
    active_cols = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                active_rows.add(r)
                active_cols.add(c)

    # Mark all cells in active rows and cols
    for r in range(rows):
        for c in range(cols):
            if r in active_rows or c in active_cols:
                result[r][c] = fill_color

    return result

filled = fill_rows_cols_ordered(input_grid, 3)
action = {"action": "submit", "grid": filled}
